def assign_new(%Driver{assigns: assigns} = driver, key, value) do
  %{driver | assigns: Map.put_new(assigns, key, value)}
end

def assign(%Driver{assigns: assigns} = driver, key, value) do
  %{driver | assigns: Map.put(assigns, key, value)}
end

def set_busy(%Driver{} = driver, flag) when is_boolean(flag) do
  %{driver | busy: flag}
end

def compile(graph)
def compile(%Graph{primitives: primitives}) do
  {ops, _} =
    compile_primitive(
      Script.start(),
      primitives[0],
      primitives,
      %Compiler{reqs: Scenic.Primitive.Style.default()}
    )

  {:ok, Script.finish(ops)}
end

def round(line)
def round({p0, p1}) do
  {Math.Vector2.round(p0), Math.Vector2.round(p1)}
end

def trunc(line)
def trunc({p0, p1}) do
  {Math.Vector2.trunc(p0), Math.Vector2.trunc(p1)}
end

def get_xy(matrix)
def get_xy(
      <<_::binary-size(12), x::float-size(32)-native, _::binary-size(12),
        y::float-size(32)-native, _::binary>>
    ) do
  {x, y}
end

def close?(matrix_a, matrix_b, tolerance \\ +1.0e-6)
def close?(<<_::binary-size(@matrix_size)>> = a, <<_::binary-size(@matrix_size)>> = b, t)
    when is_float(t) do
  nif_close(a, b, t)
end

def zero() do
  @matrix_zero
end

def identity() do
  @matrix_identity
end

def add(vector2_a, vector2_b)
def add({ax, ay}, {bx, by}) do
  {ax + bx, ay + by}
end

def div(vector2_a, vector2_b)
def div({ax, ay}, s) when is_number(s) do
  {ax / s, ay / s}
end

def invert(vector_2)
def invert({x, y}) do
  {-x, -y}
end

def mul(vector2_a, vector2_b)
def mul({ax, ay}, s) when is_number(s) do
  {ax * s, ay * s}
end

def normalize(vector2)
def normalize({ax, ay}) do
  case Vector2.length({ax, ay}) do
    +0.0 -> {ax, ay}
    len -> {ax / len, ay / len}
  end
end

def round(vector_2)
def round({x, y}) do
  {Kernel.round(x), Kernel.round(y)}
end

def sub(vector2_a, vector2_b)
def sub({ax, ay}, {bx, by}) do
  {ax - bx, ay - by}
end

def trunc(vector_2)
def trunc({x, y}) do
  {Kernel.trunc(x), Kernel.trunc(y)}
end

