def handle_node(%{errors: errs} = node, errors) do
  {node, :lists.reverse(errs) ++ errors}
end
def handle_node(%{raw: raw} = node, errors) do
  {_, errors} = Blueprint.prewalk(raw, errors, &handle_node/2)
  {node, errors}
end
def handle_node(node, acc) do
  {node, acc}
end

