def create(user, authorization \\ nil) do
  with {:ok, token} <- do_create(user, authorization) do
    Pleroma.Workers.PurgeExpiredToken.enqueue(%{
      token_id: token.id,
      valid_until: DateTime.from_naive!(token.valid_until, "Etc/UTC"),
      mod: __MODULE__
    })

    {:ok, token}
  end
end

def validate_token(secret, token, options) when is_binary(secret) and is_binary(token) do
  case :pot.valid_totp(token, secret, options) do
    true -> {:ok, :pass}
    false -> {:error, :invalid_token}
  end
end
def validate_token(_, _, _) do
  {:error, :invalid_secret_and_token}
end

