def handle_event(
      @finch_request_event,
      %{duration: duration},
      %{request: request, result: result},
      config
    ) do
  if request.host == config.remote_host do
    result =
      case result do
        {:ok, %Finch.Response{status: status}} when status >= 200 and status < 300 -> "ok"
        {:ok, %Finch.Response{}} -> "bad_status"
        {:ok, _} -> "stream"
        {:error, %{reason: :timeout}} -> "timeout_error"
        {:error, _} -> "unknown_error"
      end

    :telemetry.execute(
      @persistor_request_event,
      %{duration: duration},
      %{result: result, path: normalize_path(request.path)}
    )
  end

  :ok
end
def handle_event(
      @finch_connect_event,
      %{duration: duration},
      %{host: host} = meta,
      config
    ) do
  if host == config.remote_host do
    :telemetry.execute(
      @persistor_connect_event,
      %{duration: duration},
      %{
        status:
          if meta[:error] do
            "error"
          else
            "ok"
          end
      }
    )
  end

  :ok
end
def handle_event(
      @finch_send_event,
      %{duration: duration},
      %{request: request} = meta,
      config
    ) do
  if request.host == config.remote_host do
    :telemetry.execute(
      @persistor_send_event,
      %{duration: duration},
      %{
        status:
          if meta[:error] do
            "error"
          else
            "ok"
          end
      }
    )
  end

  :ok
end
def handle_event(
      @finch_receive_event,
      %{duration: duration},
      %{request: request} = meta,
      config
    ) do
  if request.host == config.remote_host do
    status = meta[:status] || 0

    :telemetry.execute(
      @persistor_receive_event,
      %{duration: duration},
      %{
        status:
          if meta[:error] || status < 200 || status > 299 do
            "error"
          else
            "ok"
          end
      }
    )
  end

  :ok
end

