definition:
def query(conn, statement, params, opts \\ []) do
  query = %Query{statement: statement}
  opts = Keyword.put_new(opts, :parameters, params)

  case DBConnection.prepare_execute(conn, query, params, opts) do
    {:ok, _query, result} -> {:ok, result}
    {:error, err} -> {:error, err}
  end
end

