def lookup_import(env, name_arity)
def lookup_import(
      %{__struct__: Macro.Env, functions: functions, macros: macros},
      {name, arity} = pair
    )
    when is_atom(name) and is_integer(arity) do
  f =
    for {mod, pairs} <- functions, :ordsets.is_element(pair, pairs) do
      {:function, mod}
    end

  m =
    for {mod, pairs} <- macros, :ordsets.is_element(pair, pairs) do
      {:macro, mod}
    end

  f ++ m
end

