def featurizer_resize_size(images, size)
def featurizer_resize_size(_images, %{height: height, width: width}) do
  {height, width}
end
def featurizer_resize_size(images, %{shortest_edge: size}) do
  {height, width} = images_spatial_sizes(images)

  {short, long} =
    if height < width do
      {height, width}
    else
      {width, height}
    end

  out_short = size
  out_long = floor(size * long / short)

  if height < width do
    {out_short, out_long}
  else
    {out_long, out_short}
  end
end

