def select_repo(igniter, opts \\ []) do
  label = Keyword.get(opts, :label, "Which repo should be used?")

  case list_repos(igniter) do
    {igniter, []} -> {igniter, nil}
    {igniter, [repo]} -> {igniter, repo}
    {igniter, repos} -> {igniter, Igniter.Util.IO.select(label, repos, display: &inspect/1)}
  end
end

def select_endpoint(igniter, router \\ nil, label \\ "Which endpoint should be used") do
  if router do
    case endpoints_for_router(igniter, router) do
      {igniter, []} ->
        {igniter, nil}

      {igniter, [endpoint]} ->
        {igniter, endpoint}

      {igniter, endpoints} ->
        {igniter, Igniter.Util.IO.select(label, endpoints, display: &inspect/1)}
    end
  else
    {igniter, endpoints} =
      Igniter.Project.Module.find_all_matching_modules(igniter, fn _mod, zipper ->
        Enum.find_value(@endpoint_modules, fn endpoint_module ->
          Igniter.Code.Module.move_to_use(zipper, endpoint_module) != :error
        end)
      end)

    case endpoints do
      [] -> {igniter, nil}
      [endpoint] -> {igniter, endpoint}
      endpoints -> {igniter, Igniter.Util.IO.select(label, endpoints, display: &inspect/1)}
    end
  end
end

def select_router(igniter, label \\ "Which router should be modified?") do
  case list_routers(igniter) do
    {igniter, []} -> {igniter, nil}
    {igniter, [router]} -> {igniter, router}
    {igniter, routers} -> {igniter, Igniter.Util.IO.select(label, routers, display: &inspect/1)}
  end
end

