def listen(stream, state, fun) when is_function(fun, 2) do
  async(fn ->
    Enum.reduce_while(stream, state, fn item, state ->
      case safe_apply(fun, [item, state], "Kino.listen") do
        {:ok, {:cont, state}} -> {:cont, state}
        {:ok, :halt} -> {:halt, state}
        {:error, _, _} -> {:cont, state}
      end
    end)
  end)
end

