    when is_list(multi_route_trips) do
  Enum.reduce(multi_route_trips, %{}, fn %MultiRouteTrip{
                                           added_route_id: route_id,
                                           trip_id: trip_id
                                         },
                                         acc ->
    update_in(acc, [Access.key(trip_id, [])], fn route_ids -> [route_id | route_ids] end)
  end)
end

