def parse_job_id(id) when is_integer(id) do
  {:ok, id}
end
def parse_job_id(string) when is_binary(string) do
  case Integer.parse(string) do
    {id, ""} -> {:ok, id}
    _ -> {:error, "id must be an integer or an integer-parsble string, got: \"#{string}\""}
  end
end

def report_job_status(job_status, not_found_message) do
  case job_status do
    nil -> {:error, :not_found, not_found_message}
    queued when queued in ~w[scheduled available] -> {:ok, %{status: :queued}}
    executing when executing in ~w[executing retryable] -> {:ok, %{status: :executing}}
    "completed" -> {:ok, %{status: :success}}
    "discarded" -> {:ok, %{status: :failure}}
    "cancelled" -> {:ok, %{status: :cancelled}}
  end
end

def validate_zip_file(conn) do
  case get_req_header(conn, "content-type") do
    ["application/zip"] -> :ok
    [] -> {:error, "missing content-type header"}
    [other] -> {:error, "expected content-type of application/zip, got: #{other}"}
    others -> {:error, "expected a single content-type header, got multiple: #{inspect(others)}"}
  end
end

def parse_date(nil) do
  {:error, :invalid_date}
end
def parse_date(date_string) do
  case Date.from_iso8601(date_string) do
    {:ok, date} -> {:ok, date}
    {:error, _} -> {:error, :invalid_date}
  end
end

