definition:
def handle_event(acc, "initial-response", %{}) do
  acc
end
def handle_event(
      %{state: state, events: events} = acc,
      "SubscribeToShardEvent",
      %{"ContinuationSequenceNumber" => sequence_number} = event
    )
    when is_binary(sequence_number) do
  %{
    acc
    | state: %{state | resume_position: {:after_sequence_number, sequence_number}},
      events: [event | events]
  }
end
def handle_event(
      %{events: events} = acc,
      "SubscribeToShardEvent",
      %{"ContinuationSequenceNumber" => nil} = event
    ) do
  %{acc | events: [event | events], result: :closed}
end

def handle_response({:status, _ref, code}, %{state: state} = acc) do
  %{acc | state: %{state | status: code}}
end
def handle_response({:headers, _ref, headers}, %{state: state} = acc) do
  %{acc | state: %{state | headers: headers}}
end
def handle_response({:data, _ref, ""}, acc) do
  acc
end
def handle_response({:data, _ref, data}, %{state: %{status: 200}} = acc) do
  handle_data(data, acc)
end
def handle_response({:data, _ref, data}, %{state: %{buffer: buffer} = state} = acc) do
  %{acc | state: %{state | buffer: [buffer, data]}}
end
def handle_response({:done, _ref}, %{state: %{status: 200}, result: :ok} = acc) do
  %{acc | result: :done}
end
def handle_response({:done, _ref}, %{state: %{status: 200}} = acc) do
  acc
end
def handle_response({:done, _ref}, %{state: %{status: status, headers: headers}} = acc)
    when status in 300..399 do
  location = :proplists.get_value("location", headers)
  %{acc | result: {:http_error, status, to_string(location)}}
end
def handle_response(
      {:done, _ref},
      %{state: %{status: status, headers: headers, buffer: buffer}} = acc
    )
    when status in 400..499 do
  @content_type <> _ = :proplists.get_value("content-type", headers)
  %{"__type" => type, "message" => message} = json_codec().decode!(buffer)
  %{acc | result: {type, message}}
end
def handle_response({:done, _ref}, %{state: %{status: status, buffer: buffer}} = acc)
    when status >= 500 do
  %{acc | result: {:http_error, status, IO.iodata_to_binary(buffer)}}
end

def maybe_rerequest(%{conn: conn, active?: false} = state) do
  if HTTP2.open?(conn, :write) do
    case state |> build_request() |> then(&request(conn, &1)) do
      {:ok, conn} -> {:ok, %{state | conn: conn, active?: true}}
      {:error, conn, error} -> {:error, %{state | conn: conn}, error}
    end
  else
    log(
      "event=subscribe_to_shard_connection_closed_for_writing consumer_arn=#{state.consumer_arn}"
    )

    {:ok, state}
  end
end
def maybe_rerequest(%{active?: true} = state) do
  {:ok, state}
end

def starting_position_data(type) when type in [:latest, :trim_horizon] do
  %{"Type" => type |> to_string() |> String.upcase()}
end
def starting_position_data({type, sequence_number})
    when type in [:at_sequence_number, :after_sequence_number] and is_binary(sequence_number) do
  %{"Type" => type |> to_string() |> String.upcase(), "SequenceNumber" => sequence_number}
end
def starting_position_data({:at_timestamp, %DateTime{} = timestamp}) do
  %{"Type" => "AT_TIMESTAMP", "Timestamp" => DateTime.to_unix(timestamp)}
end

def subscribe_operation(consumer_arn, shard_id, starting_position) do
  ExAws.Operation.JSON.new(:kinesis, %{
    data: %{
      "ConsumerARN" => consumer_arn,
      "ShardId" => shard_id,
      "StartingPosition" => starting_position_data(starting_position)
    },
    headers: [{"x-amz-target", @target_operation}, {"content-type", @content_type}]
  })
end

