def next_active_period_active_time([], _time) do
  :past
end
def next_active_period_active_time(
      [{start_time, end_time} | rest_of_active_periods],
      time
    ) do
  cond do
    ends_before?(end_time, time) -> next_active_period_active_time(rest_of_active_periods, time)
    DateTime.before?(start_time, time) -> {:current, start_time}
    true -> {:future, start_time}
  end
end

