def parse_token(value, good, bad) when value in ["inner_express_bus", "outer_express_bus"] do
  {filter_insert(good, name: "express_bus"), bad}
end
def parse_token(value, good, bad) when value in @fare_name do
  {filter_insert(good, name: value), bad}
end
def parse_token(value, good, bad) when value in @fare_ride do
  {filter_insert(good, name: value), bad}
end
def parse_token(value, good, bad) when value in @fare_media do
  {filter_insert(good, includes_media: value), bad}
end
def parse_token(value, good, bad) when value in @fare_reduced do
  {filter_insert(good, reduced: (value == "reduced" && "any") || value), bad}
end
def parse_token(value, good, bad) when value in @fare_duration do
  {filter_insert(good, duration: value), bad}
end
def parse_token(value, good, bad) when value in @zone_type do
  {filter_insert(good, zone_type: value), bad}
end
def parse_token(value, good, bad) when value in @zone_id do
  {[{:zone_id, value} | good], bad}
