def broadcast(broadcast_fn) do
  @predictions_phoenix_pub_sub |> broadcast_fn.("predictions", :broadcast) |> log_errors()
end

def start_stream({keys, filters}) do
  DynamicSupervisor.start_child(
    __MODULE__,
    {Worker, [{keys, filters}, via_tuple(filters)]}
  )
end

def do_new(fetch_keys, topic) do
  case streams_from_fetch_keys(fetch_keys) do
    [] -> {:error, :no_streams_found}
    streams -> %__MODULE__{topic: topic, fetch_keys: fetch_keys, streams: Enum.uniq(streams)}
  end
end

