def parse_stop_time_update(stu_json) do
  nonrev = stu_json["schedule_relationship"] == "SKIPPED"

  stu = %Realtime.Data.TripUpdate.StopTimeUpdate{
    station_id: Realtime.Data.Stations.platforms_to_stations()[stu_json["stop_id"]]
  }

  if nonrev do
    %{stu | predicted_arrival_time: stu_json["passthrough_time"]}
  else
    %{
      stu
      | predicted_arrival_time: stu_json["arrival"] && stu_json["arrival"]["time"],
        predicted_departure_time: stu_json["departure"] && stu_json["departure"]["time"]
    }
  end
end

def match_trips(vehicle_positions, trip_updates, ocs_trips) do
  ocs_trips_by_uid = Enum.into(ocs_trips, %{}, fn trip -> {trip.uid, trip} end)

  Enum.map(vehicle_positions, fn vp ->
    vehicle_id = Realtime.Data.unprefixed_vehicle_id(vp.vehicle_id)

    current_trip =
      Enum.filter(ocs_trips, fn trip ->
        trip.train_uid == vehicle_id && trip.assigned_at != nil
      end)
      |> Enum.max_by(
        fn trip -> trip.assigned_at end,
        DateTime,
        fn -> nil end
      )

    next = next_trip_chain(ocs_trips_by_uid, vehicle_id, current_trip)
    ocs_current_and_next = %{current: current_trip, next: next}
    trip_update = Enum.find(trip_updates, fn trip_update -> trip_update.trip_id == vp.trip_id end)
    %Vehicle{position: vp, trip_update: trip_update, ocs_trips: ocs_current_and_next}
  end)
  |> populate_actual_departures(DateTime.utc_now())
end

