def create_headway_section([
      %RDS{state: %{route_id: route_id, direction_name: direction_name_one, range: range}}
      | [%RDS{state: %{route_id: route_id, direction_name: direction_name_two, range: range}}]
    ])
    when direction_name_one != direction_name_two do
  %HeadwaySection{route: route_id, time_range: range, headsign: nil}
end
def create_headway_section(
      [
        %RDS{
          headsign: first_headsign,
          state: %Headways{
            route_id: first_route_id,
            direction_name: first_direction_name,
            range: first_range
          }
        }
        | _
      ] = destinations
    ) do
  %HeadwaySection{
    route: first_route_id,
    time_range: first_range,
    headsign:
      cond do
        Enum.all?(destinations, fn %RDS{headsign: headsign} -> headsign == first_headsign end) ->
          first_headsign

        Enum.all?(
          destinations,
          fn %RDS{
               state: %Headways{route_id: other_route_id, direction_name: other_direction_name}
             } ->
            other_direction_name == first_direction_name and other_route_id == first_route_id
          end
        ) ->
          first_direction_name

        true ->
          nil
      end
  }
end

def departure_rows_from_state(%RDS{state: %Countdowns{departures: departures}}) do
  departures
end
def departure_rows_from_state(%RDS{
      state: %FirstTrip{first_scheduled_departure: first_scheduled_departure}
    }) do
  [{first_scheduled_departure, :first_trip}]
end
def departure_rows_from_state(%RDS{
      state: %ServiceEnded{last_scheduled_departure: last_scheduled_departure}
    }) do
  [{last_scheduled_departure, :last_trip}]
end
def departure_rows_from_state(%RDS{state: %NoService{}}) do
  []
end

def map_to_departure_section(:error, _, _) do
  %NoDataSection{}
end
def map_to_departure_section({:ok, []}, _, _) do
  %NoDataSection{}
end
def map_to_departure_section({:ok, rds_list}, bidirectional, section_count) do
  num_departures_per_section = div(@max_departures_per_rotation, section_count)

  cond do
    headways?(rds_list) ->
      create_headway_section(rds_list)

    no_service?(rds_list) ->
      %NoServiceSection{
        routes:
          rds_list
          |> Enum.flat_map(fn %RDS{state: %NoService{routes: routes}} -> routes end)
          |> Enum.uniq()
      }

    service_ended?(rds_list) ->
      %OvernightSection{
        routes:
          rds_list
          |> Enum.map(fn %RDS{
                           state: %ServiceEnded{
                             last_scheduled_departure: last_scheduled_departure
                           }
                         } ->
            Departure.route(last_scheduled_departure)
          end)
          |> Enum.uniq()
      }

    true ->
      %NormalSection{
        rows:
          create_and_sort_rows(rds_list)
          |> maybe_make_bidirectional(bidirectional)
          |> Enum.take(num_departures_per_section),
        layout: %Layout{},
        header: %Header{}
      }
  end
end

def instances(
      %Screen{
        app_params: %Screen.PreFare{
          elevator_status: %ScreensConfig.ElevatorStatus{parent_station_id: station_id}
        }
      },
      _now
    ) do
  {:ok, alerts} = @alert.fetch(activities: [:using_wheelchair], include_all?: true)

  active_closures =
    alerts
    |> Enum.filter(&Alert.happening_now?/1)
    |> Enum.flat_map(fn alert ->
      case Closure.from_alert(alert) do
        {:ok, closure} -> [closure]
        :error -> []
      end
    end)

  relevant_station_ids =
    case @route_pattern.fetch(%{canonical?: true, stop_ids: [station_id]}) do
      {:ok, patterns} ->
        patterns |> Enum.filter(&subway_route?/1) |> Enum.flat_map(&station_ids/1)

      :error ->
        []
    end

  [
    %ElevatorWidget{
      closures: active_closures,
      home_station_id: station_id,
      relevant_station_ids: MapSet.new(relevant_station_ids)
    }
  ]
end

def get_distance(home_stop_id, home_stop_distance_map, informed_entity)
def get_distance(_home_stop_id, _home_stop_distance_map, %InformedEntity{stop: nil}) do
  0
end
def get_distance(home_stop_id, home_stop_distance_map, %InformedEntity{
      route: "Green" <> _,
      stop: %Stop{id: ie_stop_id}
    })
    when home_stop_id in @gl_trunk_stop_ids and ie_stop_id in @gl_eastbound_split_stops do
  Map.get(home_stop_distance_map, "place-lech", @default_distance)
end
def get_distance(home_stop_id, home_stop_distance_map, %{
      route: "Green" <> _,
      stop: %{id: ie_stop_id}
    })
    when home_stop_id in @gl_trunk_stop_ids and ie_stop_id not in @gl_trunk_stop_ids do
  Map.get(home_stop_distance_map, "place-kencl", @default_distance)
end
def get_distance(_, home_stop_distance_map, %InformedEntity{stop: %{id: stop_id}}) do
  Map.get(home_stop_distance_map, stop_id, @default_distance)
end

