    ) do
  %{status: "Shuttle Bus", location: Utils.get_location(informed_entities, route_id)}
end
def serialize_alert(
      %{alert: %Alert{effect: :suspension, informed_entities: informed_entities}},
      route_id
    ) do
  status =
    if Utils.alert_is_whole_route?(informed_entities) do
      "SERVICE SUSPENDED"
    else
      "Suspension"
    end

  %{status: status, location: Utils.get_location(informed_entities, route_id)}
end
def serialize_alert(
      %{alert: %Alert{effect: :station_closure, informed_entities: informed_entities} = alert},
      route_id
    ) do
  child_platforms_at_informed_stations =
    alert
    |> Alert.informed_parent_stations()
    |> Enum.flat_map(
      &case &1.stop.child_stops do
        nil -> []
        child_stops -> child_stops
      end
    )
    |> Stop.filter_subway_platforms()

  case Alert.station_closure_type(alert, child_platforms_at_informed_stations) do
    :partial_closure ->
      platform_names =
        informed_entities
        |> Enum.map(& &1.stop.platform_name)
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()

      %{
        status: "Stop Skipped",
        location:
          Utils.get_stop_name_with_platform(
            informed_entities,
            platform_names,
            route_id
          )
      }

    :partial_closure_multiple_stops ->
      num_parent_stations =
        alert |> Alert.informed_parent_stations() |> Enum.uniq_by(& &1.stop) |> Enum.count()

      %{
        status:
          Cldr.Message.format!("{num_parent_stations, plural, =1 {Stop} other {# Stops}} Skipped",
            num_parent_stations: num_parent_stations
          ),
        location: %{full: @mbta_alerts_url, abbrev: @mbta_alerts_url},
        station_count: num_parent_stations
      }

    :full_station_closure ->
      stop_names = Utils.get_stop_names_from_ies(informed_entities, route_id)
      {status, location} = Utils.format_station_closure(stop_names)
      %{status: status, location: location, station_count: length(stop_names)}
  end
end
def serialize_alert(
      %{
        alert: %Alert{
          effect: :delay,
          cause: :single_tracking,
          severity: 1,
          informed_entities: informed_entities
        }
      },
      route_id
    ) do
  %{status: "Single Tracking", location: Utils.get_location(informed_entities, route_id)}
end
def serialize_alert(
      %{
        alert: %Alert{effect: :delay, cause: cause, informed_entities: informed_entities} = alert
      },
      route_id
    ) do
  location =
    cond do
      Utils.alert_is_whole_route?(informed_entities) -> nil
      cause == :single_tracking -> %{full: "Due to Single Tracking", abbrev: "Single Tracking"}
      true -> Utils.get_location(informed_entities, route_id)
    end

  %{status: "Delays #{Alert.delay_description(alert)}", location: location}
end
def serialize_alert(
      %{alert: %Alert{effect: :service_change, informed_entities: informed_entities}},
      route_id
    ) do
  location = Utils.get_location(informed_entities, route_id)
  %{status: "Service Change", location: location}
end

