def handle_connection(socket, state) do
  case sniff_wire(socket) do
    {:transitmaster, data} -> {:switch, TablespoonTcp.Handler, data, state}
    {:unknown, data} -> {:switch, Bandit.HTTP1.Handler, data, state}
    _ -> {:close, state}
  end
