def sniff_wire(socket) do
  case ThousandIsland.Socket.recv(socket, @transitmaster_header_size) do
    {:ok, @transitmaster_header} -> {:transitmaster, @transitmaster_header}
    {:ok, other} -> {:unknown, other}
    {:error, error} -> {:error, error}
  end
end

