    ) do
  with {:member, true} <- {:member, Actors.member?(actor_id, group_id)},
       %Actor{} = group <- Actors.get_actor(group_id),
       args <- Map.update(args, :picture, nil, fn picture -> process_picture(picture, group) end),
       args <- extract_pictures_from_post_body(args, actor_id),
       {:ok, _, %Post{} = post} <-
         Actions.Create.create(
           :post,
           args |> Map.put(:author_id, actor_id) |> Map.put(:attributed_to_id, group_id),
           true,
           %{}
         ) do
    {:ok, post}
  else
    {:member, _} -> {:error, dgettext("errors", "Profile is not member of group")}
    {:error, error} -> {:error, error}
  end
end
