def delete_post(
      _parent,
      %{id: post_id},
      %{context: %{current_actor: %Actor{id: actor_id} = actor}} = _resolution
    ) do
  with {:uuid, {:ok, _uuid}} <- {:uuid, Ecto.UUID.cast(post_id)},
       {:post, %Post{attributed_to: %Actor{id: group_id}} = post} <-
