  }
end

def activity_types do
  @activity_types
end

def get_actor_by_url(url, preload \\ false)
def get_actor_by_url(nil, _preload) do
  {:error, :actor_not_found}
end
def get_actor_by_url(url, preload) do
  case Repo.get_by(Actor, url: url) do
    nil -> {:error, :actor_not_found}
    actor -> {:ok, preload_followers(actor, preload)}
  end
end

def groups_query do
  from(a in Actor, where: a.type == ^:Group, where: a.visibility == ^:public)
end

def administrator_members_for_group_query(group_id) do
  from(m in Member,
    where: m.parent_id == ^group_id and m.role in ^@administrator_roles,
    preload: [:actor]
  )
end

def group_query do
  from(a in Actor, where: a.type == ^:Group)
end

def create_follower(attrs \\ %{}) do
  case %Follower{} |> Follower.changeset(attrs) |> Repo.insert() do
    {:ok, %Follower{} = follower} -> {:ok, Repo.preload(follower, [:actor, :target_actor])}
    {:error, %Ecto.Changeset{} = err} -> {:error, err}
  end
end

def filter_local(query) do
  from(a in query, where: is_nil(a.domain))
end

def follower_by_url(url) do
  from(f in Follower, where: f.url == ^url, preload: [:actor, :target_actor])
end

def get_group_by_actor_id(actor_id) do
  case Repo.get_by(Actor, id: actor_id, type: :Group) do
    nil -> {:error, :group_not_found}
    actor -> {:ok, actor}
  end
end

def filter_external(query) do
  from(a in query, where: not is_nil(a.domain))
end

def get_member(actor_id, parent_id) do
  case Repo.get_by(Member, actor_id: actor_id, parent_id: parent_id) do
    nil -> {:error, :member_not_found}
    member -> {:ok, member}
  end
end

def follower_by_followed_and_following_query(followed_id, follower_id) do
  from(f in Follower,
    where: f.target_actor_id == ^followed_id and f.actor_id == ^follower_id,
    preload: [:actor, :target_actor]
  )
end

def administrator_members_for_actor_query(actor_id) do
  from(m in Member,
    where: m.actor_id == ^actor_id and m.role in ^@administrator_roles,
    select: m.parent_id
  )
end

def create_member(attrs \\ %{}) do
  case %Member{}
       |> Member.changeset(attrs)
       |> Repo.insert(
         on_conflict: {:replace_all_except, [:id, :url, :actor_id, :parent_id]},
         conflict_target: [:actor_id, :parent_id],
         returning: true
       ) do
    {:ok, %Member{} = member} -> {:ok, Repo.preload(member, [:actor, :parent, :invited_by])}
    {:error, %Ecto.Changeset{} = err} -> {:error, err}
  end
end

def person_query do
  from(a in Actor, where: a.type == ^:Person)
end

def members_for_actor_query(actor_id) do
  from(m in Member, where: m.actor_id == ^actor_id, preload: [:parent, :invited_by])
end

