    where: split_part(fragment("file->>'url'"), "?", 1) == ^url
  )
end

def tags_for_post_query(post_id) do
  from(t in Tag, join: p in "posts_tags", on: t.id == p.tag_id, where: p.post_id == ^post_id)
end

def count_reports_query do
  from(r in Report, where: r.status == ^:open)
end

def sort(query, sort, direction) do
  from(query, order_by: [{^direction, ^sort}])
end

def init(_, opts) do
  {:ok, opts}
end

