def legacy_notifier_enqueue(args) do
  LegacyNotifierBuilder.enqueue(
    :legacy_notify,
    @common_params |> Map.merge(maybe_inserted_at()) |> Map.merge(args)
  )
end

def notify(
      :mentionned,
      %Comment{actor_id: actor_id, id: comment_id, mentions: mentions},
      %Event{uuid: uuid, title: title},
      _options
    )
    when length(mentions) > 0 do
  legacy_notifier_enqueue(%{
    "subject" => :event_comment_mention,
    "subject_params" => %{event_uuid: uuid, event_title: title},
    "author_id" => actor_id,
    "object_id" => to_string(comment_id),
    "mentions" => Enum.map(mentions, & &1.actor_id)
  })

  {:ok, :enqueued}
end
def notify(
      :announcement,
      %Comment{actor_id: actor_id, is_announcement: true, id: comment_id},
      %Event{id: event_id, uuid: uuid, title: title},
      _options
    ) do
  legacy_notifier_enqueue(%{
    "subject" => :participation_event_comment,
    "subject_params" => %{event_id: event_id, event_uuid: uuid, event_title: title},
    "author_id" => actor_id,
    "object_id" => to_string(comment_id)
  })

  {:ok, :enqueued}
end
def notify(
      :announcement,
      %Comment{
        actor_id: actor_id,
        in_reply_to_comment_id: in_reply_to_comment_id,
        id: comment_id
      },
      %Event{uuid: uuid, title: title, attributed_to: %Actor{type: :Group, id: group_id}},
      options
    ) do
  ActivityBuilder.enqueue(:build_activity, %{
    "type" => "event",
    "subject" => Keyword.fetch!(options, :subject),
    "subject_params" => %{
      event_title: title,
      event_uuid: uuid,
      comment_reply_to: !is_nil(in_reply_to_comment_id)
    },
    "group_id" => group_id,
    "author_id" => actor_id,
    "object_type" => "comment",
    "object_id" => to_string(comment_id),
    "inserted_at" => DateTime.utc_now()
  })

  {:ok, :enqueued}
end
def notify(
      :organizer,
      %Comment{
        actor_id: actor_id,
        in_reply_to_comment_id: in_reply_to_comment_id,
        id: comment_id,
        uuid: comment_uuid
      } = comment,
      %Event{
        uuid: event_uuid,
        title: title,
        attributed_to: nil,
        organizer_actor_id: organizer_actor_id
      },
      _options
    )
    when actor_id !== organizer_actor_id do
  legacy_notifier_enqueue(%{
    "subject" => :event_new_comment,
    "subject_params" => %{
      event_title: title,
      event_uuid: event_uuid,
      comment_reply_to: !is_nil(in_reply_to_comment_id),
      comment_uuid: comment_uuid,
      comment_reply_to_uuid: reply_to_comment_uuid(comment)
    },
    "author_id" => actor_id,
    "object_id" => to_string(comment_id)
  })

  {:ok, :enqueued}
end
def notify(_, _, _, _) do
  {:ok, :skipped}
end

def can_send_event_announcement?(
      %Conversation{event: %Event{attributed_to_id: attributed_to_id}},
      %Comment{actor_id: actor_id}
    )
    when not is_nil(attributed_to_id) do
  attributed_to_id == actor_id or Actors.member?(actor_id, attributed_to_id)
end
def can_send_event_announcement?(
      %Conversation{event: %Event{organizer_actor_id: organizer_actor_id}},
      %Comment{actor_id: actor_id}
    )
    when not is_nil(organizer_actor_id) do
  organizer_actor_id == actor_id
end
def can_send_event_announcement?(_, _) do
  false
end

def send_participant_notifications(
      subject,
      %Conversation{id: conversation_id} = conversation,
      %Comment{actor_id: actor_id, text: last_comment_text} = comment,
      _options
    )
    when subject in [
           "conversation_created",
           "conversation_replied",
           "conversation_event_announcement"
         ] do
  conversation_id
  |> Conversations.list_conversation_participants_for_conversation()
  |> Enum.each(fn %ConversationParticipant{
                    id: conversation_participant_id,
                    actor_id: conversation_participant_actor_id
                  } = conversation_participant ->
    if actor_id != conversation_participant_actor_id and
         can_send_event_announcement?(conversation, comment) do
      LegacyNotifierBuilder.enqueue(
        :legacy_notify,
        %{
          "subject" => subject,
          "subject_params" =>
            Map.merge(
              %{
                conversation_id: conversation_id,
                conversation_participant_id: conversation_participant_id,
                conversation_text: last_comment_text
              },
              event_subject_params(conversation)
            ),
          "type" => :conversation,
          "object_type" => :conversation,
          "author_id" => actor_id,
          "object_id" => to_string(conversation_id),
          "participant" => Map.take(conversation_participant, [:id, :actor_id])
        }
      )
    end
  end)

  {:ok, :enqueued}
end
def send_participant_notifications(_, _, _, _) do
  {:ok, :skipped}
end

def send_mention_notifications(
      subject,
      %Discussion{
        id: discussion_id,
        title: title,
        slug: slug,
        actor: %Actor{id: group_id, type: :Group}
      },
