def schemas(conn, _params) do
  relay = Relay.get_actor()

  links =
    @node_info_supported_versions
    |> Enum.map(fn version ->
      %{rel: @node_info_schema_uri <> version, href: url(~p"/.well-known/nodeinfo/#{version}")}
