def filter(
      %Upload{tempfile: file, content_type: "image" <> _, width: width, height: height} = upload
    ) do
  {new_width, new_height} = sizes = limit_sizes({width, height})
  file |> Mogrify.open() |> Mogrify.resize(string(sizes)) |> Mogrify.save(in_place: true)
  {:ok, :filtered, %Upload{upload | width: new_width, height: new_height}}
end
def filter(_) do
  {:ok, :noop}
end

