def cache_forget(engine, alarm_id) do
  new_cache = Map.delete(engine.cache, alarm_id)
  action = {:forget, alarm_id}
  new_actions_r = [action | engine.actions_r]
  %{engine | cache: new_cache, actions_r: new_actions_r}
end

