def run_elixir(cmd) do
  {result, _env} = Code.eval_string(cmd)
  {:ok, inspect(result)}
catch
  kind, value -> {:error, Exception.format(kind, value, __STACKTRACE__)}
end

def run_lfe(cmd) do
  {value, _} = apply(:lfe_shell, :run_string, [cmd])
  {:ok, apply(:lfe_io, :prettyprint1, [value, 30])}
catch
  kind, value -> {:error, Exception.format(kind, value, __STACKTRACE__)}
end

def add_subsystem(%__MODULE__{} = opts, subsystem_spec) do
  %{opts | subsystems: Enum.uniq_by([subsystem_spec | opts.subsystems], &elem(&1, 0))}
end

def remove_subsystem(%__MODULE__{} = opts, subsystem_name) do
  %{opts | subsystems: Enum.reject(opts.subsystems, &(elem(&1, 0) == subsystem_name))}
end

def add_rule(config, rule) do
  %{config | rules: [rule | config.rules]}
end

