def list_archived_blog_posts(member) do
  case categories_allowed_to_post(member) do
    [] ->
      {:error, :not_allowed_to_post}

    categories ->
      query =
        from(p in Post,
          where: p.category in ^categories and p.status != :published,
          order_by: [desc: p.published_at]
        )

      {:ok, Repo.all(query)}
  end
end

def unapproved_events() do
  from(p in Event, where: p.approved == false, order_by: [p.inserted_at]) |> Repo.all()
end

def unapproved_events_count() do
  from(p in Event, where: p.approved == false, select: count(p.id)) |> Repo.one()
end

def get_working_group_by_slug(slug) do
  case Repo.one(Query.get_wg_by_slug(slug)) do
    %WorkingGroup{} = wg -> {:ok, wg}
    _ -> {:error, :not_found}
  end
end

def get_wg_by_id(id) do
  from(wg in wg_query(), where: wg.id == ^id)
end

def get_wg_by_slug(slug) do
  from(wg in wg_query(), where: wg.slug == ^slug)
end

def get_wg_report_by_member_id(id) do
  from(r in WorkingGroupReport, where: r.member_id == ^id)
end

